from pathlib import Path
import subprocess, hashlib, sys
root=Path('.')
# Build HEAD tree map path -> blob sha
out=subprocess.check_output(['git','ls-tree','-r','-z','HEAD'])
entries=out.split(b'\0')
head={}
for e in entries:
    if not e: continue
    meta,path=e.split(b'\t',1)
    parts=meta.split()
    if len(parts)>=3:
        head[path.decode('utf-8','surrogateescape')]=parts[2].decode()
modified=[]; deleted=[]; errors=[]
for path, oid in head.items():
    p=root/path
    if not p.exists():
        deleted.append(path); continue
    try:
        data=p.read_bytes()
    except Exception as ex:
        errors.append((path, repr(ex))); continue
    h=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
    if h != oid:
        modified.append(path)
print('tracked_total', len(head))
print('modified_count', len(modified))
print('deleted_count', len(deleted))
print('error_count', len(errors))
print('\nmodified_first_120')
for p in modified[:120]: print(p)
print('\ndeleted_first_120')
for p in deleted[:120]: print(p)
